// Api: the request contract
public sealed record CreateOrderRequest(int CustomerId, DateOnly DeliverOn);
// Application: the same fields again, behind a pass-through service
public sealed record CreateOrderDto(int CustomerId, DateOnly DeliverOn);
// Domain: the same fields again
public sealed record OrderData(int CustomerId, DateOnly DeliverOn);
public interface IOrderDomainService { Task<int> CreateAsync(OrderData d); }

public sealed class OrderAppService(IOrderDomainService domain)
{
    public Task<int> CreateAsync(CreateOrderDto dto) =>
        domain.CreateAsync(new OrderData(dto.CustomerId, dto.DeliverOn));
}
// Infrastructure: the same fields again, for EF Core
public sealed class OrderRow
{
    public int CustomerId { get; set; }
    public DateOnly DeliverOn { get; set; }
}
// One new field: four types, three mappings, four projects

// Ordering module: the only type other modules can see
public interface IOrdering
{
    Task<int> PlaceAsync(
        int customerId, DateOnly deliverOn, CancellationToken ct);
}

// Everything else stays internal, and can keep its own layers
internal sealed class Ordering(OrderingDb db) : IOrdering
{
    public async Task<int> PlaceAsync(
        int customerId, DateOnly deliverOn, CancellationToken ct)
    {
        var order = Order.Place(customerId, deliverOn); // rules live here
        db.Orders.Add(order);
        await db.SaveChangesAsync(ct);
        return order.Id;
    }
}
// Billing and Shipping depend on IOrdering, never on Order or OrderingDb
